const icons={home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16"/>',ball:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="3"/><path d="M3 12h6m6 0h6"/>',book:'<path d="M12 5C9 3 5 3 2 4v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-3-1-7-1-10 1v15"/>',chart:'<path d="M4 3v18h18M8 16v-5m5 5V7m5 9V4"/>',settings:'<path d="M10 3h4l1 3 3 1 3 3v4l-3 1-1 3-3 3h-4l-1-3-3-1-3-3v-4l3-1 1-3z"/><circle cx="12" cy="12" r="3"/>',arrow:'<path d="M4 12h15m-6-6 6 6-6 6"/>',play:'<path d="m9 5 11 7-11 7z"/>',bolt:'<path d="m14 2-9 12h7l-2 8 9-12h-7z"/>',star:'<path d="m12 3 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',check:'<path d="m5 12 4 4L20 5"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 12 3 3 5-6"/>',leaf:'<path d="M20 3C7 2 2 6 4 14s16 7 16-11zM5 20 17 7"/>',pause:'<path d="M8 5v14M16 5v14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',sound:'<path d="m3 9 5 0 5-5v16l-5-5H3zM17 8q5 4 0 8m2-11q8 7 0 14"/>',gift:'<path d="M3 9h18v5H3zM5 14v8h14v-8M12 9v13"/><path d="M12 9C1 9 6-2 12 9c6-11 11 0 0 0"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-5 5 5-5 5 5M4 16v5h16v-5"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 5 8 15 8 15S25 10 20 5z"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
const icon=(n)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.star}</svg>`;
let collectionTab='partners';let offlineReady=false;let actions={},view='home',engine=null,bank=[],poemMeta=[],data,selectId=25,filterSubject='all',bankAccess=false,bankKind='poems',bankSearch='',bankPage=0,quizInterval=null,toastTimer,readyTimer=null,portraitPaused=false,saveFailed=false;
const app=$('#app'),modalRoot=$('#modal-root');
function act(name,fn){actions[name]=fn;return name}
function button(text,name,cls='btn',disabled=false){return `<button class="${cls}" data-action="${name}" ${disabled?'disabled':''}>${text}</button>`}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function save(){try{persist(data);saveFailed=false}catch(e){if(!saveFailed){saveFailed=true;toast('本地保存失败，请前往设置导出备份。')}}}
let audio,musicNodes=[];
function sound(kind){if(!data.settings.sound)return;try{audio||=new (window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const now=audio.currentTime,notes={collect:[660,880],skill:[180,360,720],correct:[523,659,784],wrong:[330,280],hurt:[140,90],shield:[440,660],win:[523,659,784,1046]}[kind]||[440];notes.forEach((hz,i)=>{const osc=audio.createOscillator(),gain=audio.createGain();osc.type=kind==='skill'?'triangle':'sine';osc.frequency.value=hz;gain.gain.setValueAtTime(.0001,now+i*.08);gain.gain.exponentialRampToValueAtTime(.06,now+i*.08+.012);gain.gain.exponentialRampToValueAtTime(.0001,now+i*.08+.22);osc.connect(gain);gain.connect(audio.destination);osc.start(now+i*.08);osc.stop(now+i*.08+.24)})}catch{}}
function music(){for(const n of musicNodes){try{n.stop()}catch{}}musicNodes=[];if(!data.settings.music||document.hidden)return;try{audio||=new (window.AudioContext||window.webkitAudioContext)();audio.resume();[130.81,196,261.63].forEach((hz,i)=>{const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=hz;o.type='sine';g.gain.value=.008/(i+1);o.connect(g);g.connect(audio.destination);o.start();musicNodes.push(o)})}catch{}}
function modal(html,classes=''){modalRoot.innerHTML=`<div class="overlay"><section class="modal ${classes}" role="dialog" aria-modal="true">${html}</section></div>`;requestAnimationFrame(()=>$('.modal button,.modal input')?.focus({preventScroll:true}))}
function closeModal(){modalRoot.innerHTML=''}
function confirmBox(title,message,yes){modal(`<div class="eyebrow">冒险提示</div><h2>${title}</h2><p>${message}</p><div class="actions">${button('取消',act('cancelConfirm',()=>closeModal()),'btn')}${button('确认',act('yesConfirm',()=>{closeModal();yes()}),'btn gold')}</div>`)}
function shell(body){const p=partner(data.selected),r=recordFor(data,p.id),nav=[['home','home','冒险首页'],['journey','map','冒险地图'],['partners','ball','伙伴图鉴'],['records','chart','复习记录'],['mistakes','book','我的错题'],['settings','settings','游戏设置']];return `<div class="shell"><aside class="sidebar"><a href="#" class="brand" data-action="nav-home"><div class="brand-ball"></div><div><strong>训练家小站</strong><small>POKÉMON TRAINER</small></div></a><div class="nav-caption">探索你的每一份可能</div><nav class="nav">${nav.map(([id,ic,text])=>`<button class="${view===id?'active':''}" data-action="nav-${id}" aria-label="${text}">${icon(ic)}<span>${text}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="offline-pill"><span class="status-dot"></span><span id="offline-label">${offlineReady?'离线就绪 · 自动保存':'本地存档 · 自动保存'}</span></div><footer>一点好奇，一点勇气。<br>每次冒险，都有新的收获。<br><a href="../" style="color:#8fa89d">← 返回训练家小站</a></footer></div></aside><main class="content page-${view}"><header class="topbar"><div class="breadcrumbs">${icon('home')}<span>训练家小站</span><span>/</span><span>能量岛冒险</span></div><div class="profile"><span class="local-date">${new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'short'}).format(new Date())}</span><img class="avatar" src="${art(appearance(p,r))}" alt="${esc(formName(p,r))}"><div class="profile-name">小小训练家<small>LET’S GROW TOGETHER</small></div>${button(icon('settings'),'nav-settings','btn small')}</div></header>${body}</main></div>`}
function render(next=view){if(engine){engine.destroy();engine=null}clearInterval(quizInterval);clearTimeout(readyTimer);document.body.classList.remove('game-screen');if(next!=='bank')bankAccess=false;view=next;actions={};closeModal();['home','journey','partners','records','mistakes','settings'].forEach(x=>act('nav-'+x,()=>render(x)));document.body.classList.toggle('reduced',data.settings.reduced);const pages={home:homeView,journey:journeyView,partners:partnersView,records:recordsView,mistakes:mistakesView,settings:settingsView,setup:setupView,bank:bankView,learning:learningView};app.innerHTML=shell((pages[next]||homeView)());if(next==='bank')bindBank();window.scrollTo(0,0)}
function summaryCards(){const s=statsSummary(data),p=recordFor(data,data.selected);return `<div class="stat-grid">${[['bolt',p.xp,'成长值','伙伴每一步，都算数'],['check',s.total,'道题','一起温习过的知识'],['shield',s.rate==null?'—':s.rate+'%','','首次作答正确率'],['book',s.due,'项','等待再次相遇的知识']].map(([i,v,u,t])=>`<div class="stat-card"><div class="stat-icon">${icon(i)}</div><div><strong>${v}</strong><span class="unit">${u}</span><p>${t}</p></div></div>`).join('')}</div>`}
function homeView(){act('learning',()=>render('learning'));const s=statsSummary(data),p=partner(data.selected),daily=dayLedger(data),reviewed=Math.min(3,daily.reviewed.length);act('newGame',()=>startSetup());act('continue',()=>continueGame());act('training',()=>startTraining());act('choosePartner',()=>render('partners'));const spark=Array.from({length:15},(_,i)=>`<i class="spark" style="left:${(i*37)%90+5}%;top:${(i*29)%80+10}%;animation-delay:-${i*.4}s"></i>`).join('');return `<section class="hero"><div class="hero-copy"><div class="eyebrow">ENERGY ISLAND ADVENTURE</div><h1>小小训练家，<br>开启你的<em>能量冒险</em></h1><p>收集能量，挑战首领，答题进化。</p><div class="actions">${button(icon('play')+(data.run?'继续冒险':'出发去冒险')+icon('arrow'),data.run?'continue':'newGame','btn gold')}${button(data.run?'开启新一轮':'玩法指南',data.run?'newGame':act('guide',showGuide),'btn ghost')}</div><div class="hero-foot"><span>✧ 六站奇妙旅程</span><span>◷ 约12–18分钟</span><span>◇ 边玩边复习</span></div></div><div class="hero-art"><div class="orbit"></div><span class="hero-symbol">EXPLORE · LEARN · EVOLVE</span><div class="hero-leaf"></div>${spark}<i class="cube c1"></i><i class="cube c2"></i><i class="cube c3"></i><i class="cube c4"></i><img class="hero-main" src="${art(appearance(p,recordFor(data,p.id)))}" alt="${formName(p,recordFor(data,p.id))}官方立绘"><img class="hero-side" src="${art(p.id===1?7:1)}" alt="宝可梦伙伴"></div></section>${summaryCards()}<div class="home-lower"><section><div class="section-title"><div><h2>你的冒险伙伴</h2></div>${button('查看全部 '+icon('arrow'),'choosePartner','text-button')}</div><div class="partner-preview">${PARTNERS.slice(0,4).map((p,i)=>{act('partner-'+p.id,()=>showPartner(p.id));return `<button class="partner-tile" style="--tile:${['#ebdcb0','#eac7b4','#bed7e1','#c2d9c4'][i]}" data-action="partner-${p.id}"><span class="type-badge">${TYPES[p.type].symbol} ${TYPES[p.type].name}系</span><span class="number">NO.${String(p.id).padStart(3,'0')}</span><img src="${art(appearance(p,recordFor(data,p.id)))}" alt="${formName(p,recordFor(data,p.id))}"><div class="partner-name-row"><strong>${formName(p,recordFor(data,p.id))}</strong><span>↗</span></div><p>${i===0?'充满好奇 · 元气满满':i===1?'勇敢热情 · 活力无限':i===2?'沉稳可靠 · 温柔坚定':'自然之友 · 生机盎然'}</p></button>`}).join('')}</div></section><section><div class="section-title"><div><h2>今日小目标</h2></div></div><div class="task-card"><div class="eyebrow">DAILY DISCOVERY</div><h3>${s.due||reviewed?'让旧知识变成新力量':'知识的小种子'}</h3><p>${s.due||reviewed?'独立答对3个不同的到期知识点，领取额外成长值。':'冒险中答题，明天再来复习。'}</p><div class="progress"><i style="width:${reviewed/3*100}%"></i></div><div class="task-meta"><span>${reviewed} / 3 项复习</span><span>奖励 +3 成长值</span></div>${button(daily.task?'今日目标已完成 ✓':'开始复习 '+icon('arrow'),'training','btn',!s.due&&!Object.keys(data.mistakes).length)}</div></section></div><div class="source-footer">非官方宝可梦学习游戏 · 角色及官方立绘版权归各自权利人所有 · 学习进度仅保存在此设备</div>`}
function showGuide(){modal(`<div class="eyebrow">YOUR FIRST ADVENTURE</div><h2>收集勇气，也收集知识</h2><div class="steps"><div class="info-note">01　点击伙伴出发，题目从全量题库随机抽取。</div><div class="info-note">02　左手移动，靠近收集方块；普攻自动发射，右手释放招式。</div><div class="info-note">03　收集、装置、补给与首领节点触发答题；不限时，答对充能。</div><div class="info-note">04　完成关卡目标，挑战三只伊布，解锁新的伙伴。</div></div><p>电脑可使用方向键 / WASD，空格放招式，E交互；也可点击场景移动。iPad使用摇杆与右侧按钮。</p><div class="actions">${button('我准备好了',act('guideClose',()=>closeModal()),'btn gold')}</div>`)}
function startSetup(){const go=()=>{selectId=data.selected;render('setup')};if(data.run)confirmBox('开始新一轮冒险？','当前冒险的关卡和战斗资源将结束，伙伴成长、图鉴与学习记录完整保留。',go);else go()}
function setupView(){return `<div class="page-head"><div class="eyebrow">CHOOSE YOUR PARTNER</div><h1>选择伙伴，即刻出发</h1><p>${data.started?'通关可结识新伙伴。':'点击一位伙伴，开始冒险。'}</p></div><div class="partner-grid">${PARTNERS.map(p=>{const unlocked=!data.started||data.unlocked.includes(p.id),r=recordFor(data,p.id);act('select-'+p.id,()=>{selectId=p.id;data.selected=p.id;if(!data.started){data.started=true;data.unlocked=[p.id]}save();beginRun()});return `<button data-action="select-${p.id}" class="select-partner ${selectId===p.id?'selected':''} ${unlocked?'':'locked'}" ${!unlocked?'disabled':''} style="--type:${TYPES[p.type].color}">${selectId===p.id?'<span class="selected-check">✓</span>':''}<span class="type-badge">${TYPES[p.type].symbol} ${TYPES[p.type].name}系</span><img src="${art(appearance(p,r))}" alt="${formName(p,r)}"><h3>${formName(p,r)}</h3><p>${esc(p.note)}</p><small>${unlocked?`${r.xp} 成长值 · ${formName(p,r)}`:'通关后可结识'}</small><div class="progress"><i style="width:${Math.min(100,r.xp/220*100)}%"></i></div></button>`}).join('')}</div>`}
function journeyView(){act('mapStart',()=>data.run?continueGame():startSetup());return `<div class="page-head"><div class="eyebrow">YOUR ADVENTURE MAP</div><h1>六站旅程</h1></div><div class="journey-grid">${STAGES.map((s,i)=>`<div class="journey-step ${data.run?.stage===i?'active':''}"><div class="step-num">${data.run?.stage>i?'✓':String(i+1).padStart(2,'0')}</div><div><h3>${s.name}</h3><p>${['收集6块同属性方块，抵达出口','花费能量激活2座装置，抵达出口','收集8块同属性方块，躲避障碍','战胜第一只伊布首领','探索2个补给点，为最终战准备','战胜剩余两只伊布，完成冒险'][i]}</p></div>${s.kind==='boss'?`<img src="${art(i===3?135:136)}" alt="伊布首领">`:''}<span class="step-state">${data.run?.stage>i?'已完成':data.run?.stage===i?'正在探索':'等待出发'}</span></div>`).join('')}</div><div class="setup-bar"><p>${data.run?'伙伴与进度都已为你保留。':'一次冒险约12–18分钟，可以随时保存退出。'}</p>${button((data.run?'继续冒险':'开启冒险')+icon('arrow'),'mapStart','btn gold')}</div>`}
function evolutionStrip(p,r){const ids=[...p.chain,p.mega?(r.mega||p.mega):p.chain[2]],names=[...p.forms,p.mega?p.megaName:'终阶招式'];return `<div class="evolution-track">${ids.map((id,i)=>`<div class="evolution-node ${r.xp>=[0,25,70,220][i]?'reached':''}"><img src="${art(id)}" alt="${names[i]}"><small>${[0,25,70,220][i]}</small></div>`).join('')}</div>`}
function partnersView(){act('tab-partners',()=>{collectionTab='partners';render('partners')});act('tab-bosses',()=>{collectionTab='bosses';render('partners')});return `<div class="page-head"><h1>伙伴图鉴</h1><div class="collection-tabs" role="tablist" aria-label="图鉴分类">${[['partners','伙伴 · '+data.unlocked.length+'/8'],['bosses','首领 · '+data.bossSeen.length+'/3']].map(([id,label])=>`<button role="tab" aria-selected="${collectionTab===id}" class="chip ${collectionTab===id?'chosen':''}" data-action="tab-${id}">${label}</button>`).join('')}</div></div><div role="tabpanel" class="partner-grid ${collectionTab==='bosses'?'boss-grid':''}">${collectionTab==='partners'?PARTNERS.map(p=>{const r=recordFor(data,p.id),unlocked=data.unlocked.includes(p.id);act('detail-'+p.id,()=>showPartner(p.id));return `<button class="select-partner ${!unlocked&&data.started?'locked':''}" data-action="detail-${p.id}" style="--type:${TYPES[p.type].color}"><span class="type-badge">${TYPES[p.type].symbol} ${TYPES[p.type].name}系</span><img class="partner-portrait" src="${art(appearance(p,r))}" alt="${formName(p,r)}"><h3>${formName(p,r)}</h3><small>${unlocked?r.xp+' 成长值':data.started?'等待结识':'可选初始伙伴'}</small><div class="progress"><i style="width:${Math.min(100,r.xp/220*100)}%"></i></div>${evolutionStrip(p,r)}</button>`}).join(''):BOSSES.map(b=>`<div class="select-partner ${data.bossSeen.includes(b.id)?'':'locked'}"><img src="${art(b.id)}" alt="${b.name}"><h3>${b.name}</h3><small>${data.bossSeen.includes(b.id)?'已战胜':'尚未战胜'}</small></div>`).join('')}</div>`}
function showPartner(id){const p=partner(id),r=recordFor(data,id),unlocked=data.unlocked.includes(id)||!data.started;act('partnerChoose',()=>{data.selected=id;selectId=id;save();closeModal();startSetup()});act('partnerClose',()=>closeModal());modal(`<button class="modal-close" data-action="partnerClose" aria-label="关闭">×</button><div class="eyebrow">PARTNER NO.${String(p.id).padStart(3,'0')}</div><h2>${formName(p,r)} <span class="type-badge" style="color:${TYPES[p.type].color}">${TYPES[p.type].name}系</span></h2><p>${esc(p.note)}</p><div class="sprite-stage"><img src="assets/sprites/${appearance(p,r)}.gif" alt="${p.name}动态精灵"><span>准备好，和你一起出发。</span></div><div class="gallery-forms">${p.chain.map((id,i)=>`<div class="gallery-form ${r.xp<[0,25,70][i]?'inactive':''}"><img src="${art(id)}" alt="${p.forms[i]}"><p>${p.forms[i]}</p><small>${[0,25,70][i]} 成长值</small></div>`).join('')}</div><div class="milestones"><div class="milestone"><strong>${r.xp}</strong><p>当前成长值</p></div><div class="milestone"><strong>${r.xp>=220?'Lv.2':'Lv.1'}</strong><p>${p.moves[r.xp>=220?1:0]}</p></div><div class="milestone"><strong>220</strong><p>终阶目标</p></div></div><p>25 / 70成长阶段提升普攻与招式；220成长值解锁终阶招式${p.mega?'与专属强化形态':'与专属终阶光效'}。自定义强化形态属于本游戏设定。</p><div class="actions">${button('返回','partnerClose','btn')}${button(unlocked?'和它一起冒险':'通关后可以结识','partnerChoose','btn gold',!unlocked)}</div>`,'wide')}
function recordsView(){act('learning',()=>render('learning'));act('recordsTrain',()=>startTraining());const summary=statsSummary(data);return `<div class="page-head"><div class="eyebrow">LITTLE STEPS, BIG GROWTH</div><h1>你的每一份进步，都在这里</h1><p>首次作答才计入正确率；看懂解析后的订正，也是值得肯定的一步。</p></div>${summaryCards()}<div class="split" style="margin-top:24px"><section class="panel"><h3>学科温习记录</h3><div class="subject-bars">${Object.entries(SUBJECTS).map(([key,name])=>{const h=data.history.filter(x=>x.subject===key),right=h.filter(x=>x.correct).length;return `<div class="subject-bar"><span>${name}</span><div class="progress"><i style="width:${h.length?right/h.length*100:0}%"></i></div><span>${h.length?Math.round(right/h.length*100)+'%':'—'}</span></div><p style="font-size:10px;margin-top:-10px">${h.length}道独立作答 · ${right}道首次答对</p>`}).join('')}</div></section><section class="panel"><h3>最近七天</h3><p>一点点重复，让知识扎下根。</p><div class="chart-month">${Array.from({length:7},(_,i)=>{const date=new Date(Date.now()-(6-i)*DAY),key=localDay(date.getTime()),n=data.history.filter(x=>localDay(x.at)===key).length;return `<div class="chart-day"><strong>${n||''}</strong><i style="height:${Math.min(75,Math.max(3,n*5))}px"></i><small>${date.getMonth()+1}/${date.getDate()}</small></div>`}).join('')}</div></section></div><div class="section-title"><div><h2>知识成长清单</h2><p>${summary.mastered}项已掌握 · ${summary.due}项到期复习</p></div><div class="inline-actions">${button('知识清单','learning','text-button')}${button('开始复习 '+icon('arrow'),'recordsTrain','text-button',!data.history.length)}</div></div><div class="chips">${['all',...Object.keys(SUBJECTS)].map(k=>button(k==='all'?'全部':SUBJECTS[k],act('recordFilter-'+k,()=>{filterSubject=k;render('records')}),'chip '+(filterSubject===k?'chosen':''))).join('')}</div><div class="record-list">${Object.entries(data.knowledge).filter(([,k])=>filterSubject==='all'||k.subject===filterSubject).sort((a,b)=>b[1].last-a[1].last).slice(0,80).map(([,k])=>`<article class="record-item"><div class="record-top"><h3>${esc(k.title)}</h3><span class="tag ${k.state}">${stateLabel(k.state)}</span></div><p>${SUBJECTS[k.subject]} · 首次答对 ${k.right} 次 / 答错 ${k.wrong} 次 · ${k.due?'下次复习：'+formatDate(k.due):'等待间隔重测'}${k.abilities?'<br>'+Object.entries(k.abilities).map(([type,a])=>CATEGORY[type]+': '+a.right+'对 / '+a.wrong+'错').join(' · '):''}</p></article>`).join('')||'<div class="info-note">还没有复习记录。带上伙伴开始第一场冒险吧。</div>'}</div>`}
function stateLabel(state){return {weak:'待巩固',review:'复习中',mastered:'已掌握',new:'未练习'}[state]||'未练习'}
function formatDate(t){return new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(t)}
function mistakesView(){act('mistakesTrain',()=>startTraining());const rows=Object.values(data.mistakes).filter(m=>filterSubject==='all'||m.question.subject===filterSubject).sort((a,b)=>b.last-a.last);return `<div class="page-head"><div class="eyebrow">A MISTAKE IS A NEW BEGINNING</div><h1>把“还不会”，变成“我记住了”</h1><p>错题自动收录；订正后隔几道再见，之后按1、3、7天复习。</p></div><div class="setup-bar" style="position:static;margin:0 0 22px"><p>共 <strong>${Object.keys(data.mistakes).length}</strong> 道错题 · 每次训练最多10道</p>${button('复习训练 '+icon('arrow'),'mistakesTrain','btn gold',!Object.keys(data.mistakes).length)}</div><div class="chips">${['all',...Object.keys(SUBJECTS)].map(k=>button(k==='all'?'全部':SUBJECTS[k],act('mistakeFilter-'+k,()=>{filterSubject=k;render('mistakes')}),'chip '+(filterSubject===k?'chosen':''))).join('')}</div><div class="record-list">${rows.slice(0,100).map(m=>{const q=m.question,k=data.knowledge[q.key];return `<article class="record-item"><div class="record-top"><h3>${esc(q.stem)}</h3><span class="tag ${k?.state}">${stateLabel(k?.state)}</span></div><p>我的作答：<span style="color:#eeb6a5">${esc(answerText(q,m.answer))}</span><br>正确答案：<span style="color:#b3dbc6">${esc(answerText(q,q.answer))}</span><br>${esc(q.analysis)}</p><p style="font-size:10px">${SUBJECTS[q.subject]} · 累计错误 ${m.count} 次 · 最近 ${formatDate(m.last)} · ${k?.due?'下次复习 '+formatDate(k.due):'已安排延迟重测'}</p></article>`}).join('')||'<div class="empty"><img src="'+art(7)+'" alt="杰尼龟"><h2>每一次尝试，都值得鼓励</h2><p>出现错题时，会在这里为你整理好。</p></div>'}</div>`}
function settingsView(){act('export',exportSave);act('import',()=>$('#import-file').click());act('reset',()=>confirmBox('清空全部学习与冒险进度？','伙伴、图鉴、错题和复习计划都会删除，此操作不可撤销。建议先导出备份。',()=>{data=defaults();save();render('home');toast('已创建新的本地档案')}));act('poemBank',()=>openBank('poems'));act('idiomBank',()=>openBank('idioms'));['sound','music','reduced'].forEach(k=>act('toggle-'+k,()=>{data.settings[k]=!data.settings[k];save();if(k==='music')music();render('settings')}));setTimeout(()=>{const inp=$('#import-file');if(inp)inp.onchange=importSave},0);return `<div class="page-head"><div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>游戏设置</h1></div><div class="split"><section class="panel"><h3>学习与体验</h3>${[['sound','交互音效','收集、招式和答案提示。'],['music','环境音乐','柔和的合成氛围音。'],['reduced','减少动态效果','关闭页面浮动、震动与强烈特效。']].map(([key,title,desc])=>`<div class="setting-row"><div><strong>${title}</strong><small>${desc}</small></div><button class="toggle ${data.settings[key]?'on':''}" data-action="toggle-${key}" aria-label="${title}" aria-pressed="${data.settings[key]}"></button></div>`).join('')}</section><section><div class="panel"><h3>本地档案与备份</h3><p>所有进度保存在当前浏览器，离线可继续。卸载应用或清理网站数据可能移除存档，建议定期导出备份。</p><div class="inline-actions" style="margin-top:20px">${button(icon('download')+'导出备份','export','btn small')}${button(icon('upload')+'导入备份','import','btn small')}</div><input type="file" id="import-file" accept="application/json,.json" class="hide"><div class="setting-row" style="margin-top:10px"><div><strong>清空全部进度</strong><small>会删除所有学习与伙伴记录。</small></div>${button('清空','reset','btn small danger')}</div></div><div class="panel" style="margin-top:20px"><h3>家长题库清单</h3><p>查看全部题目、答案及解析，需验证访问密码。</p><div class="inline-actions" style="margin-top:18px">${button(icon('lock')+'古诗题库','poemBank','btn small')}${button(icon('lock')+'成语题库','idiomBank','btn small')}</div></div></section></div>`}

function exportSave(){save();const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='能量岛冒险-备份-'+localDay()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
async function importSave(e){const file=e.target.files[0];if(!file)return;try{if(file.size>30*1024*1024)throw Error('备份文件过大');const d=JSON.parse(await file.text());if(!validSave(d))throw Error('备份格式或版本不兼容');for(const p of Object.values(d.partners))if(!Number.isFinite(p.xp)||p.xp<0)throw Error('伙伴数据无效');confirmBox('导入并覆盖本地档案？',`备份时间：${formatDate(d.updated||d.created)}；包含${d.unlocked.length}位伙伴、${d.history.length}次作答。确认后覆盖当前档案。`,()=>{data=d;save();render('home');toast('备份导入成功')})}catch(error){toast('无法导入：'+error.message)}}
function openBank(kind){bankKind=kind;bankSearch='';bankPage=0;if(bankAccess){render('bank');return}act('passCancel',()=>closeModal());act('passConfirm',()=>{if($('#passcode').value==='0023'){bankAccess=true;render('bank')}else $('#pass-error').textContent='密码不正确，请重新输入。'});modal(`<div class="eyebrow">PARENT ACCESS</div><h2>家长题库清单</h2><p>请输入4位数字访问密码。</p><input id="passcode" class="field pass-input" inputmode="numeric" maxlength="4" type="password" autocomplete="off" aria-label="4位数字密码"><p id="pass-error" style="color:#eab2a0;min-height:24px"></p><div class="actions">${button('取消','passCancel','btn')}${button('进入题库','passConfirm','btn gold')}</div>`);const inp=$('#passcode');inp.oninput=()=>inp.value=inp.value.replace(/\D/g,'').slice(0,4);inp.onkeydown=e=>{if(e.key==='Enter')actions.passConfirm();if(e.key==='Escape')closeModal()};inp.focus()}
function bankView(){act('bankPoems',()=>{bankKind='poems';bankPage=0;bankSearch='';render('bank')});act('bankIdioms',()=>{bankKind='idioms';bankPage=0;bankSearch='';render('bank')});act('bankBack',()=>{bankAccess=false;render('settings')});return `<div class="page-head"><div class="eyebrow">QUESTION LIBRARY</div><h1>${bankKind==='poems'?'古诗':'成语'}题库清单</h1><p>查阅完整题干、正确答案与解析。家长访问密码仅作入口限制。</p></div><div class="inline-actions">${button('古诗98题','bankPoems','chip '+(bankKind==='poems'?'chosen':''))}${button('成语993题','bankIdioms','chip '+(bankKind==='idioms'?'chosen':''))}${button('退出题库','bankBack','btn small')}</div><div class="search-row"><input id="bank-search" class="field" placeholder="搜索篇目 / 作者 / 成语 / 题号" value="${esc(bankSearch)}"></div><div id="bank-results">${bankRows()}</div>`}
function bankRows(){const rows=bank.filter(q=>(bankKind==='poems'?!!q.poem:q.kind==='idiom')&&(q.stem+q.title+(q.author||'')+q.id).includes(bankSearch)),page=rows.slice(bankPage*30,bankPage*30+30);act('bankPrev',()=>{bankPage--;$('#bank-results').innerHTML=bankRows()});act('bankNext',()=>{bankPage++;$('#bank-results').innerHTML=bankRows()});return `<p class="muted" style="font-size:12px">共${rows.length}题 · 第${bankPage+1}/${Math.max(1,Math.ceil(rows.length/30))}页</p><div class="record-list">${page.map(q=>`<article class="record-item"><div class="record-top"><h3>${esc(q.stem)}</h3><span class="tag">${esc(q.id)}</span></div><p>${q.options.map((o,i)=>`${'ABCD'[i]}. ${esc(o)}`).join('　')}<br>答案：${esc(answerText(q,q.answer))}<br>${esc((q.analysis||'').split(/[。！]/)[0])}。</p><details><summary>查看完整解析</summary><p>${esc(q.analysis)}</p></details>${fullPoem(q)}${q.poem?`<p>${esc(q.poem)} · ${esc(q.author)} · ${esc(q.dynasty)}</p>`:''}</article>`).join('')||'<div class="info-note">没有匹配的题目。</div>'}</div><div class="inline-actions" style="margin-top:20px">${button('上一页','bankPrev','btn small',!bankPage)}${button('下一页','bankNext','btn small',(bankPage+1)*30>=rows.length)}</div>`}
function bindBank(){const input=$('#bank-search');input.oninput=()=>{bankSearch=input.value;bankPage=0;$('#bank-results').innerHTML=bankRows()}}
function fullBankSettings(settings){return {...settings,allBank:true,subjects:["math","chinese","english"],math:["multiply","add","sub"],carry:true,ten:true,english:["vocab","dialogue"],words:true,mode:"normal",untimed:true}}
function beginRun(){data.settings=fullBankSettings(data.settings);closeModal();music();const bosses=shuffle(BOSSES.map(x=>x.id));data.run={id:Date.now().toString(36),partner:selectId,settings:structuredClone(data.settings),stage:0,bossIndex:0,bosses,boost:{attack:0,skill:0,magnet:0},claimed:{},seq:0,recent:[],usedMath:[],historyStart:data.history.length,startXP:recordFor(data,selectId).xp,scene:makeScene(0),quiz:null,pending:null,started:Date.now(),tutorial:!data.tutorialDone};for(let i=0;i<4;i++)data.run.scene.blocks.push({x:360+i*110,y:430-Math.sin(i)*70,type:partner(selectId).type,seed:i});save();openGame();introStage()}
function openGame(){if(engine)engine.destroy();clearInterval(quizInterval);clearTimeout(readyTimer);closeModal();view='game';document.body.classList.add('game-screen');const run=data.run;run.settings.reduced=data.settings.reduced;const p=partner(run.partner),record=recordFor(data,run.partner);app.innerHTML=`<main class="game-shell"><header class="game-header"><div class="game-title"><div class="eyebrow">ENERGY ISLAND · ${String(run.stage+1).padStart(2,'0')} / 06</div><h2>${STAGES[run.stage].name}</h2><div class="game-steps">${STAGES.map((_,i)=>`<i class="${i<=run.stage?'done':''}"></i>`).join('')}</div></div><div class="game-stats"><div><div class="game-stat-label">伙伴生命</div><div class="hp-hearts" id="hp-hud"></div><div id="shield-hud" class="shield-label"></div></div><div class="game-xp"><img src="${art(appearance(p,record))}" alt="${p.name}"><div><p>${formName(p,record)}</p><small id="xp-hud"></small><div class="progress"><i id="xp-bar"></i></div></div></div>${button(icon('pause')+'暂停',act('pause',()=>pauseGame()),'btn small')}</div></header><section class="game-board"><canvas id="world" aria-label="宝可梦探索场景，使用摇杆或方向键移动"></canvas><div class="objective"><small>本关目标</small><strong id="objective-text"></strong></div><div class="board-note" id="quiz-next">知识挑战即将开启</div><div class="joystick" id="joystick" role="application" aria-label="拖动摇杆移动伙伴"><div class="joy-knob" id="joy-knob"></div></div><div class="energy-hud"><strong id="energy-count">3</strong><small> / 10 招式能量</small><div class="energy-pips" id="energy-pips"></div><small id="exchange-label"></small></div><div class="controls-right">${button('交互 · E',act('interact',()=>engine?.interact()),'interact-button')}<button class="skill-button" id="skill" data-action="skill">${icon('bolt')}<strong id="skill-name">${p.moves[record.xp>=220?1:0]}</strong><small id="skill-cost"></small><span class="skill-cd hide" id="skill-cd"></span></button></div><div class="keyboard-note">WASD / 方向键移动　·　空格释放招式　·　E交互　·　也可点地移动</div></section></main>`;act('skill',()=>engine?.skill());engine=new Engine($('#world'),run,record,engineEvent);bindJoystick();updateHUD()}
function engineEvent(type,payload){if(type==='hud'){updateHUD();return}if(type==='sound'){sound(payload);return}if(type==='save'){save();return}if(type==='quiz'){startQuiz();return}if(type==='supply'){showSupply(payload);return}if(type==='bossWin'||type==='stageWin'||type==='fail'){data.run.pending={kind:type,payload};save();resolvePending()}}
function updateHUD(){if(!engine||!$('#hp-hud'))return;const r=data.run,s=r.scene,p=partner(r.partner),record=recordFor(data,r.partner),st=stats(record,r.boost),stage=STAGES[r.stage];$('#hp-hud').innerHTML='♥'.repeat(s.hp)+'<i>'+'♥'.repeat(10-s.hp)+'</i>';$('#shield-hud').textContent=s.shield?'◇ 知识护盾已就绪':`知识连对 ${s.combo} / 3`;$('#xp-hud').textContent=record.xp+' 成长值';const headerImg=$('.game-xp img');const headerArt=art(appearance(p,record));if(headerImg?.getAttribute('src')!==headerArt){headerImg.src=headerArt;headerImg.alt=formName(p,record);$('.game-xp p').textContent=formName(p,record)}const next=record.xp<25?25:record.xp<70?70:220;$('#xp-bar').style.width=Math.min(100,record.xp/next*100)+'%';$('#energy-count').textContent=s.energy;$('#energy-pips').innerHTML=Array.from({length:10},(_,i)=>`<i class="${i<s.energy?'on':''}"></i>`).join('');$('#exchange-label').textContent='异属性 '+s.other+' / 3';$('#skill-cost').textContent=st.cost+'点能量';$('#skill-name').textContent=p.moves[st.lv===2?1:0];$('#skill').disabled=!s.boss||s.cooldown>0||s.energy<st.cost||s.done;$('#skill-cd').classList.toggle('hide',s.cooldown<=0);$('#skill-cd').textContent=s.cooldown.toFixed(1);$('#quiz-next').textContent='知识挑战 · 答对补充能量';$('#objective-text').textContent=stage.kind==='boss'?`挑战${BOSSES.find(b=>b.id===s.boss?.id)?.name||'伊布'} · ${r.stage===5?'最终战 '+(r.bossIndex)+'/2':'首领战'}`:stage.kind==='collect'?`收集同属性方块 ${s.collected}/${stage.goal}${engine.ready()?' · 前往右侧出口 →':''}`:stage.kind==='device'?`激活能量装置 ${s.devices.length}/2${engine.ready()?' · 前往出口 →':''}`:`探索补给点 ${s.supplies.length}/2${engine.ready()?' · 前往出口 →':''}`}
function bindJoystick(){const joy=$('#joystick'),knob=$('#joy-knob');let pointer=null;const move=e=>{if(pointer!==e.pointerId||!engine||engine.paused)return;const r=joy.getBoundingClientRect(),max=r.width*.32;let x=e.clientX-r.left-r.width/2,y=e.clientY-r.top-r.height/2;const d=Math.hypot(x,y);if(d>max){x=x/d*max;y=y/d*max}engine.joy={x:x/max,y:y/max};engine.target=null;knob.style.transform=`translate(${x}px,${y}px)`};joy.onpointerdown=e=>{if(engine.paused)return;pointer=e.pointerId;joy.setPointerCapture(pointer);move(e)};joy.onpointermove=move;joy.onpointerup=joy.onpointercancel=()=>{pointer=null;if(engine)engine.joy={x:0,y:0};knob.style.transform=''};joy.onlostpointercapture=joy.onpointerup}
function introStage(){engine.setPaused(true);const r=data.run,s=STAGES[r.stage];act('introGo',()=>{closeModal();if(r.tutorial||s.kind==='boss'){r.tutorial=false;data.tutorialDone=true;r.scene.quizReason=s.kind==='boss'?'首领挑战 · 为招式充能':'出发补给 · 为伙伴充能';save();startQuiz()}else resumeGame()});modal(`<div class="eyebrow">STAGE ${String(r.stage+1).padStart(2,'0')} · ${esc(s.tag)}</div><img class="modal-portrait" src="${art(s.kind==='boss'?r.scene.boss.id:appearance(partner(r.partner),recordFor(data,r.partner)))}" alt="本关伙伴"><h2>${s.name}</h2><p>${['用左侧摇杆移动，靠近方块自动收集。拾取6个同属性方块后，走入右侧光门。先一起完成一道知识挑战吧。','靠近两座能量装置，按“交互”激活。每座需要3点能量，完成后前往光门。','收集8个同属性方块并前往光门。注意地面发光区域，趁熄灭时绕过去。','普攻会自动瞄准首领。移动躲避有预警的攻击，收集方块并释放招式。','找到两个补给点，靠近后按“交互”。选择适合自己的补给，为最终挑战做准备。','剩下两位首领等着你！两战之间有一次安全补给；失败只重试尚未击败的首领。'][r.stage]}</p><div class="actions">${button('开始探索 '+icon('arrow'),'introGo','btn gold')}</div>`,'center')}
function resumeGame(){clearTimeout(readyTimer);closeModal();if(!engine)return;engine.setPaused(true);modalRoot.innerHTML='<div class="overlay"><div><div class="countdown">1</div><p class="countdown-note">准备出发</p></div></div>';readyTimer=setTimeout(()=>{closeModal();if(engine&&!document.hidden&&!isPortrait())engine.setPaused(false);else if(engine)pauseGame()},1000)}
function isPortrait(){return matchMedia('(orientation:portrait) and (pointer:coarse)').matches}
function continueGame(){if(!data.run){startSetup();return}music();openGame();if(data.run.complete){showWin();return}if(data.run.quiz){renderQuiz();return}if(data.run.pending){resolvePending();return}if(data.run.complete){showWin();return}const p=partner(data.run.partner),r=recordFor(data,data.run.partner);if(p.id===4&&r.xp>=220&&!r.mega){chooseMega(()=>resumeGame());return}resumeGame()}
function pauseGame(){if(!engine||data.run?.pending||data.run?.quiz)return;clearTimeout(readyTimer);engine.setPaused(true);save();act('resume',()=>resumeGame());act('saveQuit',()=>quitGame());act('guideInGame',()=>{modal(`<div class="eyebrow">CONTROLS</div><h2>慢慢来，你可以的</h2><p>摇杆 / 方向键 / WASD移动；靠近自动拾取方块。普攻免费自动释放；招式消耗能量，空格或右侧按钮释放。靠近装置或补给点，按E或“交互”。</p><p style="margin-top:12px">同属性方块+1能量；异属性每3个兑换1能量。探索节点暂停答题，不限时；答对补充2点能量，答错订正后继续。护盾可抵挡一次伤害。</p><div class="actions">${button('返回暂停',act('backPause',()=>pauseGame()),'btn gold')}</div>`)});modal(`<div class="eyebrow">TAKE A LITTLE BREAK</div><h2>冒险暂停，进步保留</h2><p>${partner(data.run.partner).name}会在这里等你。继续时有1秒准备时间。</p><div class="actions">${button('操作说明','guideInGame','btn')}${button('保存退出','saveQuit','btn')}${button('继续冒险 '+icon('play'),'resume','btn gold')}</div>`)}
function quitGame(){save();clearInterval(quizInterval);if(engine){engine.destroy();engine=null}render('home');toast(saveFailed?'保存失败，请导出备份后再离开。':'冒险已保存，随时回来继续。')}
function inheritScene(old,next){for(const key of ['hp','energy','other','shield','combo'])next[key]=old[key];return next}
function nextStage(){const r=data.run;r.stage++;r.pending=null;r.scene=inheritScene(r.scene,makeScene(r.stage,r.stage===3?r.bosses[0]:r.stage===5?r.bosses[1]:null));r.scene.hp=Math.min(10,r.scene.hp+2);if(r.stage===5)r.bossIndex=1;save();openGame();introStage()}
function resolvePending(){if(!data.run?.pending)return;const r=data.run,pending=r.pending;if(pending.kind==='fail'){showFailure();return}if(pending.kind==='bossWin'){const id=pending.payload,thresholds=claim(data,r,'boss-'+id,5);if(!data.bossSeen.includes(id))data.bossSeen.push(id);if(r.stage===5&&r.bossIndex===1){save();showEvolution(thresholds,()=>{act('finalSupply',()=>showSupply('final'));modal(`<img class="modal-portrait" src="${art(id)}" alt="已击败的首领"><div class="eyebrow">WELL DONE, TRAINER</div><h2>第一位首领，挑战成功！</h2><p>稍作休息，领取一份补给。下一位首领正在等待你。</p><span class="reward">+5 成长值</span><div class="actions">${button('领取补给','finalSupply','btn gold')}</div>`,'center')});return}if(r.stage===5&&r.bossIndex===2){const t=[...thresholds,...claim(data,r,'stage-5',2)];if(!recordFor(data,r.partner).firstWin){recordFor(data,r.partner).firstWin=true;t.push(...claim(data,r,'first-win',10))}if(data.unlocked.length===8)t.push(...claim(data,r,'all-unlocked',3));r.complete=true;save();showEvolution(t,()=>showWin());return}const stageThresholds=claim(data,r,'stage-'+r.stage,2);save();showEvolution([...thresholds,...stageThresholds],()=>stageReward(true));return}if(pending.kind==='stageWin'){const t=claim(data,r,'stage-'+r.stage,2);save();showEvolution(t,()=>stageReward(false))}}
function stageReward(boss){const r=data.run;act('stageContinue',()=>{if([0,1,2,4].includes(r.stage)&&!r.claimed['boost-'+r.stage])showBoost();else nextStage()});modal(`<img class="modal-portrait" src="${art(appearance(partner(r.partner),recordFor(data,r.partner)))}" alt="伙伴庆祝"><div class="eyebrow">ANOTHER LITTLE VICTORY</div><h2>${STAGES[r.stage].name}，完成！</h2><p>${boss?'勇气与专注，帮你战胜了首领。':'探索过的每一步，都会成为下一站的力量。'}<br>下一关恢复2点生命，能量与护盾保留。</p><span class="reward">+${boss?7:2} 成长值${boss?' · 含首领奖励':''}</span><div class="actions">${button('保存退出',act('stageQuit',()=>quitGame()),'btn')}${button([0,1,2,4].includes(r.stage)?'选择本局强化':'前往下一站','stageContinue','btn gold')}</div>`,'center')}
function showBoost(){const r=data.run;const options=[['attack','bolt','普攻强化','普攻伤害 +0.25'],['skill','star','招式强化','招式伤害 +1'],['magnet','leaf','能量吸引','吸附范围 +15%']];modal(`<div class="eyebrow">A GIFT FOR YOUR JOURNEY</div><h2>选一份力量，继续前行</h2><p>本局强化跨关保留，失败不会丢失。每项最多选择2次。</p><div class="boost-grid">${options.map(([key,ic,name,desc])=>{act('boost-'+key,()=>{if(r.claimed['boost-'+r.stage]||r.boost[key]>=2)return;r.boost[key]++;r.claimed['boost-'+r.stage]=true;save();nextStage()});return `<button class="boost-card" data-action="boost-${key}" ${r.boost[key]>=2?'disabled':''}>${icon(ic)}<strong>${name}</strong><small>${desc}</small><small>已选 ${r.boost[key]}/2</small></button>`}).join('')}</div>`,'wide')}
function showSupply(id){if(!engine)return;engine.setPaused(true);const r=data.run,s=r.scene,final=id==='final',taken=final?r.claimed.finalSupply:s.supplies.includes(id);if(taken){if(final)startSecondFinal();else resumeGame();return}const options=[['hp','heart','恢复生命','恢复3点生命',s.hp>=10],['energy','bolt','补充能量','获得5点能量',s.energy>=10],['shield','shield','知识护盾','抵挡一次伤害',s.shield]];const full=options.every(o=>o[4]);const choose=key=>{if(final)r.claimed.finalSupply=true;else s.supplies.push(id);if(key==='hp')s.hp=Math.min(10,s.hp+3);if(key==='energy')s.energy=Math.min(10,s.energy+5);if(key==='shield')s.shield=true;save();sound('collect');if(final)startSecondFinal();else resumeGame()};modal(`<div class="eyebrow">A MOMENT TO RECHARGE</div><h2>补充一点能量，再出发</h2><p>选择一份补给。已满的资源不能重复领取。</p><div class="boost-grid">${options.map(([key,ic,name,desc,disabled])=>{act('supply-'+key,()=>choose(key));return `<button class="boost-card" data-action="supply-${key}" ${disabled?'disabled':''}>${icon(ic)}<strong>${name}</strong><small>${desc}</small></button>`}).join('')}</div>${full?'<div class="actions">'+button('状态全满，继续出发',act('supply-full',()=>choose(null)),'btn gold')+'</div>':''}`,'wide')}
function startSecondFinal(){const r=data.run;r.bossIndex=2;r.scene=inheritScene(r.scene,makeScene(5,r.bosses[2]));r.pending=null;save();openGame();introStage()}
function showFailure(){const r=data.run;act('retry',()=>{const old=r.scene;r.scene=makeScene(r.stage,r.stage===3?r.bosses[0]:r.stage===5?r.bosses[r.bossIndex]:null);r.scene.shield=old.shield;r.scene.combo=old.combo;r.pending=null;save();openGame();introStage()});act('failureQuit',()=>quitGame());modal(`<img class="modal-portrait" src="${art(appearance(partner(r.partner),recordFor(data,r.partner)))}" alt="伙伴等待"><div class="eyebrow">LET’S TRY AGAIN</div><h2>休息一下，再试一次</h2><p>伙伴成长、强化与复习进度全部保留。<br>重试恢复10点生命与3点能量；已战胜的首领不会复活。</p><div class="actions">${button('保存退出','failureQuit','btn')}${button('重试本段 '+icon('arrow'),'retry','btn gold')}</div>`,'center')}
function showWin(){const r=data.run,rec=recordFor(data,r.partner),history=data.history.slice(r.historyStart),right=history.filter(x=>x.correct).length;act('unlockWin',()=>unlockPartner());modal(`<div class="eyebrow">YOU MADE IT, TRAINER</div><img class="modal-portrait" src="${art(appearance(partner(r.partner),rec))}" alt="通关伙伴"><h2>能量岛冒险，通关！</h2><p>收获知识，收获勇气，也收获了和伙伴的回忆。</p><div class="milestones"><div class="milestone"><strong>+${rec.xp-r.startXP}</strong><p>伙伴成长</p></div><div class="milestone"><strong>${history.length}</strong><p>独立答题</p></div><div class="milestone"><strong>${history.length?Math.round(right/history.length*100)+'%':'—'}</strong><p>首次正确率</p></div></div><p>${Object.entries(SUBJECTS).map(([k,v])=>`${v} ${history.filter(x=>x.subject===k).length}题`).join(' · ')}<br>${statsSummary(data).due}项知识等待复习，记得带着伙伴回来看看。</p><div class="actions">${button(data.unlocked.length<8?'结识新伙伴 '+icon('gift'):'完成冒险 '+icon('check'),'unlockWin','btn gold')}</div>`,'center')}
function unlockPartner(){const r=data.run;const locked=PARTNERS.filter(p=>!data.unlocked.includes(p.id));const finish=()=>{data.lastRun={partner:r.partner,xp:recordFor(data,r.partner).xp-r.startXP,at:Date.now()};data.run=null;save();render('home');sound('win');toast('冒险完成，新的旅程随时出发。')};if(!locked.length){finish();return}modal(`<div class="eyebrow">A NEW FRIEND AWAITS</div><h2>选择下一位冒险伙伴</h2><p>每次通关可结识一位新朋友。原伙伴的成长完整保留。</p><div class="partner-grid" style="grid-template-columns:repeat(4,1fr);margin-top:20px">${locked.map(p=>{act('unlock-'+p.id,()=>{if(!data.unlocked.includes(p.id))data.unlocked.push(p.id);finish()});return `<button class="select-partner" data-action="unlock-${p.id}"><img src="${art(p.id)}" alt="${p.name}" style="height:90px"><h3 style="font-size:13px">${p.name}</h3></button>`}).join('')}</div>`,'wide')}
function showEvolution(thresholds,done){const id=(view==='training'?data.training?.partner:data.run?.partner)||data.selected,p=partner(id),rec=recordFor(data,id);const queue=[...new Set(thresholds)].sort((a,b)=>a-b);const next=()=>{if(!queue.length){if(p.id===4&&rec.xp>=220&&!rec.mega){chooseMega(done);return}done();return}const t=queue.shift(),image=t===220?p.mega||p.chain[2]:p.chain[t===70?2:1];const name=t===220?(p.mega?p.megaName:'终阶招式解锁'):t===25&&p.id===25?'皮卡丘成长了！':p.forms[t===70?2:1];act('evolveContinue',()=>next());sound('win');modal(`<div class="eyebrow">A LITTLE SPARK BECOMES A LIGHT</div><img class="modal-portrait" src="${art(image)}" alt="${name}"><h2>${name}</h2><p>${t===220?'累积的知识化作新的力量，终阶招式已解锁。':t===25&&p.id===25?'形态没有改变，勇气与招式都更强了。':'伙伴进化了！普攻与招式获得永久提升。'}<br>${t}成长值里程碑 · 当前${rec.xp}成长值</p><div class="actions">${button('一起继续成长','evolveContinue','btn gold')}</div>`,'center evolution')};next()}
function chooseMega(done){const id=(view==='training'?data.training?.partner:data.run?.partner)||data.selected,rec=recordFor(data,id);modal(`<div class="eyebrow">YOUR PARTNER, YOUR CHOICE</div><h2>选择喷火龙的强化形态</h2><p>本次选择永久保存在伙伴档案，两种形态战斗数值相同。</p><div class="split" style="margin-top:20px">${[[10034,'X'],[10035,'Y']].map(([img,name])=>{act('mega-'+name,()=>{rec.mega=img;save();done()});return `<button class="select-partner" data-action="mega-${name}"><img src="${art(img)}" alt="超级喷火龙${name}"><h3>超级喷火龙 ${name}</h3></button>`}).join('')}</div>`)}
function session(){return view==='training'?data.training:data.run}
function quizSettings(){return fullBankSettings(view==='training'?data.training.settings:data.run.settings)}
function startQuiz(question=null){if(engine)engine.setPaused(true);const owner=session();if(!owner)return;const s=quizSettings();const q=question||chooseQuestion(data,filteredBank(bank,s),s,owner);if(!q){if(engine)resumeGame();else finishTraining();return}owner.quiz={q,remaining:timerFor(q,s),limit:timerFor(q,s),phase:'answer',answer:null,sort:[],result:null};save();renderQuiz()}
function renderQuiz(){clearInterval(quizInterval);const owner=session(),qz=owner?.quiz;if(!qz)return;qz.remaining=null;qz.limit=null;const q=qz.q,phase=qz.phase,correcting=phase==='correction',answered=phase==='result'||phase==='correctionDone',showResult=phase==='result';
 const choices=q.options.map((option,i)=>{let cls='';if(showResult){const right=Array.isArray(q.answer)?q.answer.includes(i):q.answer===i;if(!Array.isArray(q.answer)){if(right)cls='correct';else if(qz.answer===i)cls='wrong'}}if((phase==='answer'||correcting)&&qz.sort.includes(i))cls='selected';if(phase==='correctionDone')cls=Array.isArray(q.answer)||q.answer===i?'correct':'';act('answer-'+i,()=>selectAnswer(i));return `<button class="quiz-option ${cls}" data-action="answer-${i}" ${answered?'disabled':''}><span class="option-letter">${Array.isArray(q.answer)&&qz.sort.includes(i)?qz.sort.indexOf(i)+1:'ABCD'[i]}</span><span>${esc(option)}</span></button>`}).join('');
 const timer=qz.remaining!=null&&phase==='answer'?`<div class="quiz-timer" id="timer"><svg viewBox="0 0 54 54"><circle cx="27" cy="27" r="24"/><circle cx="27" cy="27" r="24"/></svg><strong id="timer-number">${Math.ceil(qz.remaining)}</strong></div>`:`<span class="tag">${correcting?'安心订正 · 不限时':phase==='answer'?'不限时':'知识已记录'}</span>`;
 act('quizSubmit',()=>submitAnswer([...qz.sort]));act('quizUndo',()=>{qz.sort.pop();renderQuiz()});act('quizReset',()=>{qz.sort=[];renderQuiz()});act('quizNext',()=>quizNext());act('quizQuit',()=>{save();clearInterval(quizInterval);if(view==='training'){render('home');toast('训练进度已保留，稍后可继续。')}else quitGame()});
 modal(`<div class="quiz-top"><div><span class="quiz-badge">${SUBJECTS[q.subject]} · ${CATEGORY[q.kind]}</span><div class="quiz-context">${view==='training'?'复习训练 · '+(owner.completed+1)+' / '+owner.queue.length:(owner.scene.quizReason||'知识补给站')+' · 场景已暂停'}</div></div>${timer}</div><h2>${esc(q.stem)}</h2>${Array.isArray(q.answer)?`<div class="quiz-sort-result">${qz.sort.length?qz.sort.map(i=>esc(q.options[i])).join(' → '):'依次点选诗句，排好后点击提交。'}</div>`:''}<div class="quiz-options ${q.kind==='sort'?'sort':''}">${choices}</div>${correcting&&qz.correctionError?'<div class="info-note">再看看解析提示，慢慢来。正确答案：'+esc(answerText(q,q.answer))+'</div>':''}${showResult?`<div class="quiz-result ${qz.result.correct?'':'wrong'}"><strong>${qz.result.correct?'✓ 答对了，知识变成了力量':'✧ 发现一个可以巩固的小知识'}</strong><p>${qz.result.correct?`成长值 +${qz.result.xp}${qz.result.xp===0?'（本知识点今日成长奖励已达上限）':''}${view!=='training'?' · '+(qz.result.battleReward||'战斗能量已补充'):''}`:'正确答案：'+esc(answerText(q,q.answer))}<br>${esc((q.analysis||'').split(/[。！]/)[0])}。</p><details><summary>查看完整解析</summary><p>${esc(q.analysis)}</p></details>${fullPoem(q)}</div>`:phase==='correctionDone'?'<div class="quiz-result"><strong>✓ 我明白了！</strong><p>订正完成。隔几道题再相遇，看看能不能独立记住。</p></div>':''}<div class="quiz-bottom"><div>${button('保存退出','quizQuit','quiz-save')}<small>${correcting?'订正不计奖励与首次正确率。':answered?'解析不会自动关闭。':'选好再点；答错不扣血。'}</small></div><div class="inline-actions">${Array.isArray(q.answer)&&!answered?button('撤销','quizUndo','btn small',!qz.sort.length)+button('重置','quizReset','btn small',!qz.sort.length)+button('提交排序','quizSubmit','btn gold',qz.sort.length!==q.options.length):''}${answered?button(phase==='correctionDone'?'继续':qz.result.correct?'继续'+(view==='training'?'复习':'冒险'):'我明白了，开始订正','quizNext','btn gold'):''}</div></div>`,'quiz');if(phase==='answer'&&qz.remaining!=null){updateTimer();let last=performance.now();quizInterval=setInterval(()=>{const now=performance.now(),dt=(now-last)/1000;last=now;if(document.hidden||isPortrait()&&view==='game')return;const before=qz.remaining;qz.remaining=Math.max(0,qz.remaining-dt);if(Math.floor(before/5)!==Math.floor(qz.remaining/5))save();updateTimer();if(qz.remaining<=0)submitAnswer(null)},100)}
}
function updateTimer(){const qz=session()?.quiz;if(!qz||!$('#timer'))return;$('#timer-number').textContent=Math.ceil(qz.remaining);$('#timer').style.setProperty('--offset',(1-qz.remaining/qz.limit)*150.8);$('#timer').classList.toggle('low',qz.remaining<=3)}
function selectAnswer(i){const owner=session(),z=owner?.quiz;if(!z||!['answer','correction'].includes(z.phase))return;if(Array.isArray(z.q.answer)){if(z.sort.includes(i))return;z.sort.push(i);save();renderQuiz()}else submitAnswer(i)}
function submitAnswer(answer){const owner=session(),z=owner?.quiz;if(!z||!['answer','correction'].includes(z.phase))return;clearInterval(quizInterval);const correct=isCorrect(z.q,answer);if(z.phase==='correction'){if(correct){z.phase='correctionDone';z.sort=Array.isArray(answer)?answer:[];sound('correct')}else{z.correctionError=true;z.sort=[];sound('wrong')}save();renderQuiz();return}
 z.answer=answer;z.sort=Array.isArray(answer)?answer:[];owner.seq=(owner.seq||0)+1;z.result=applyAnswer(data,z.q,answer,owner.partner,data.history.length+1);z.phase='result';owner.recent=[...(owner.recent||[]),{key:z.q.key,subject:z.q.subject}].slice(-20);if(z.q.subject==='math')owner.usedMath=[...(owner.usedMath||[]),z.q.id];
 if(view!=='training'){const s=data.run.scene;if(correct){const gained=Math.min(2,10-s.energy);s.energy+=gained;z.result.battleReward='招式能量 +'+gained;s.combo++;if(s.combo>=3){if(s.shield){s.energy=Math.min(10,s.energy+2);z.result.battleReward+=' · 连对额外充能'}else{s.shield=true;z.result.battleReward+=' · 知识护盾就绪'}s.combo=0}}else s.combo=0}
 save();sound(correct?'correct':'wrong');renderQuiz();updateHUD()
}
function quizNext(){const owner=session(),z=owner?.quiz;if(!z)return;if(z.phase==='result'&&!z.result.correct){z.q=shuffleQuestion(z.q);z.phase='correction';z.sort=[];z.correctionError=false;save();renderQuiz();return}if(!['result','correctionDone'].includes(z.phase))return;const thresholds=z.result?.thresholds||[];owner.quiz=null;if(view!=='training')data.run.scene.quizClock=0;save();showEvolution(thresholds,()=>{if(view==='training'){owner.completed++;save();nextTrainingQuestion()}else resumeGame()})}
function startTraining(){if(!data.started){toast('先选择伙伴并完成一次冒险答题，再来复习。');startSetup();return}if(data.training){view='training';closeModal();if(data.training.quiz)renderQuiz();else nextTrainingQuestion();return}const recentKeys=data.history.slice(-3).map(x=>x.key);const candidates=[...Object.values(data.mistakes).map(m=>m.question),...bank.filter(q=>data.knowledge[q.key]?.due&&data.knowledge[q.key].due<=Date.now())];const spaced=candidates.filter(q=>!recentKeys.includes(q.key));const unique=[...new Map(shuffle(spaced).map(q=>[q.key,q])).values()].sort((a,b)=>{const ka=data.knowledge[a.key],kb=data.knowledge[b.key];return (ka?.due||Infinity)-(kb?.due||Infinity)}).slice(0,10);if(!unique.length){toast('先练习几道其他知识，隔一会再来复习，记忆更牢。');return}let trainPartner=data.unlocked.includes(data.selected)?data.selected:data.unlocked[0];const draw=()=>{modal(`<div class="eyebrow">A LITTLE PRACTICE</div><h2>和谁一起温习？</h2><p>本次最多${unique.length}道独立题，答错先订正；不影响已保存的冒险。</p><div class="chips">${data.unlocked.map(id=>button(partner(id).name,act('trainpartner-'+id,()=>{trainPartner=id;draw()}),'chip '+(id===trainPartner?'chosen':''))).join('')}</div><div class="actions">${button('稍后再来',act('trainCancel',()=>closeModal()),'btn')}${button('开始训练',act('trainBegin',()=>{data.training={partner:trainPartner,queue:unique,completed:0,seq:0,recent:[],usedMath:[],settings:structuredClone(data.settings),quiz:null,startHistory:data.history.length,startXP:recordFor(data,trainPartner).xp};save();view='training';nextTrainingQuestion()}),'btn gold')}</div>`)};draw()}
function nextTrainingQuestion(){const t=data.training;if(!t)return;if(t.completed>=t.queue.length){finishTraining();return}view='training';if(t.quiz)renderQuiz();else startQuiz(shuffleQuestion(t.queue[t.completed]))}
function finishTraining(){const t=data.training;if(!t)return;const h=data.history.slice(t.startHistory),correct=h.filter(x=>x.correct).length;modal(`<div class="eyebrow">KNOWLEDGE TAKES ROOT</div><h2>今天又多记住了一点</h2><p>完成${h.length}道独立练习，首次答对${correct}道。<br>伙伴成长 +${recordFor(data,t.partner).xp-t.startXP}；订正已记录，后续会按间隔再次复习。</p><div class="actions">${button('完成复习',act('trainingDone',()=>{data.training=null;save();render('records')}),'btn gold')}</div>`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;e.preventDefault();const action=actions[b.dataset.action];if(action)action()});
document.addEventListener('visibilitychange',()=>{if(document.hidden){if(engine){engine.setPaused(true);if(!data.run?.quiz&&!data.run?.pending)pauseGame()}if(data)save();for(const n of musicNodes)try{n.stop()}catch{}musicNodes=[]}else if(data)music()});
window.addEventListener('resize',()=>{if(engine&&isPortrait()&&!engine.paused){portraitPaused=true;engine.setPaused(true);save()}else if(engine&&portraitPaused&&!isPortrait()){portraitPaused=false;if(!data.run?.quiz&&!data.run?.pending)pauseGame()}});
window.addEventListener('pagehide',()=>{if(data)save()});
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&engine&&!data.run.quiz&&!data.run.pending)pauseGame()});
async function init(){app.innerHTML='<div class="loadscreen"><div class="brand-ball"></div><p>正在准备伙伴与知识行囊…</p></div>';try{const [idioms,poems]=await Promise.all(['data/idioms.json','data/poems.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw Error('题库载入失败');return r.json()})));bank=[...idioms.questions.map(q=>normalizeQuestion(q,'idiom')),...poems.questions.map(q=>normalizeQuestion(q,q.type.includes('排序')?'sort':'poem')),...ENGLISH,...WORDS];poemMeta=[...new Map(poems.questions.map(q=>[q.poem,q])).values()];const loaded=load();data=loaded.data;data.settings=fullBankSettings(data.settings);if(data.run)data.run.settings=fullBankSettings(data.run.settings);render('home');if(loaded.recovered)toast('主档案异常，已恢复最近有效备份：'+formatDate(data.updated));if(loaded.corrupt&&!loaded.recovered)toast('本地档案无法读取，请在设置中导入备份。');if('serviceWorker'in navigator){navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='OFFLINE_READY'){offlineReady=true;const el=$('#offline-label');if(el)el.textContent='离线就绪 · 自动保存'}});navigator.serviceWorker.register('./sw.js').then(reg=>{if(reg.active)reg.active.postMessage({type:'STATUS'})}).catch(()=>{});}if(loaded.corrupt&&!loaded.recovered){modal(`<div class="eyebrow">SAVE RECOVERY</div><h2>本地档案需要恢复</h2><p>主档案和备份均无法读取。你可以前往设置导入导出的备份，或明确创建新档案。损坏档案尚未覆盖。</p><div class="actions">${button('前往设置导入',act('recoverSettings',()=>render('settings')),'btn')}${button('新建档案',act('recoverNew',()=>{data=defaults();save();render('home')}),'btn gold')}</div>`)}}catch(error){app.innerHTML=`<div class="loadscreen"><h2>行囊暂时没能准备好</h2><p>${esc(error.message)}。请联网打开一次，或通过本地服务器启动。</p><button class="btn gold" onclick="location.reload()">重新载入</button></div>`}}
init();

function fullPoem(q){return q.full_text?.length?`<details class="poem-full"><summary>查看全诗 · ${esc(q.poem)}</summary><p>${q.full_text.map(esc).join('<br>')}</p><small>诗句可能存在教材异文，本题以题面为准。</small></details>`:''}
function learningView(){act('learningBack',()=>render('home'));const s=fullBankSettings(data.settings);const list=[...new Map(filteredBank(bank,s).map(q=>[q.key,q])).values()];act('learningSearch',()=>{});setTimeout(()=>{const search=$('#learning-search');if(search)search.oninput=()=>{$$('[data-learning-title]').forEach(row=>row.classList.toggle('hide',!row.dataset.learningTitle.toLowerCase().includes(search.value.toLowerCase()))) }},0);return `<div class="page-head"><div class="eyebrow">YOUR LEARNING BACKPACK</div><h1>知识清单</h1><p>查看学习卡不计分，也不改变掌握状态。全量题库共含${list.length}个固定题库知识点${s.subjects.includes('math')?'，另含已开启的数学计算':''}。</p></div><div class="search-row"><input id="learning-search" class="field" placeholder="搜索诗名、成语、单词或知识点">${button('回到首页','learningBack','btn small')}</div><div class="record-list">${list.map(q=>`<article class="record-item" data-learning-title="${esc(q.title+' '+q.stem)}"><div class="record-top"><h3>${esc(q.title)}</h3><span class="tag">${SUBJECTS[q.subject]}</span></div><p>${esc(q.stem)}<br>答案：${esc(answerText(q,q.answer))}<br>${esc((q.analysis||'').split(/[。！]/)[0])}。</p><details><summary>查看完整解析</summary><p>${esc(q.analysis)}</p></details>${fullPoem(q)}</article>`).join('')||'<div class="info-note">未选择固定题库内容。数学知识点在本次设置中查看。</div>'}</div>`}
